import{_ as o,a0 as l,w as d,s as p,I as t,x as n,a1 as i,A as e,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"无需 sudo 使用 Podman 在 Linux 上运行容器 | LCTT x X-CMD","titleTemplate":false,"description":"无需 sudo 使用 Podman 在 Linux 上运行容器 | LCTT (202201) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"无需 sudo 使用 Podman 在 Linux 上运行容器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"无需 sudo 使用 Podman 在 Linux 上运行容器 | LCTT (202201) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202201/20220111 Run containers on Linux without sudo in Podman","title":"无需 sudo 使用 Podman 在 Linux 上运行容器","tag":"202201","desc":""},"relativePath":"202201/20220111 Run containers on Linux without sudo in Podman.md","filePath":"[post].md"}'),r={name:"202201/20220111 Run containers on Linux without sudo in Podman.md"};function h(m,s,g,k,b,x){const a=l("Link");return d(),p("div",null,[s[22]||(s[22]=t("h1",{id:"无需-sudo-使用-podman-在-linux-上运行容器",tabindex:"-1"},[n("无需 sudo 使用 Podman 在 Linux 上运行容器 "),t("a",{class:"header-anchor",href:"#无需-sudo-使用-podman-在-linux-上运行容器","aria-label":"Permalink to “无需 sudo 使用 Podman 在 Linux 上运行容器”"},"​")],-1)),s[23]||(s[23]=t("blockquote",null,[t("p",null,"配置你的系统使用无根容器。")],-1)),s[24]||(s[24]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202201/18/033424l111pvcc1iy0a1a1.jpg",alt:""})],-1)),t("p",null,[s[2]||(s[2]=n("容器是现代计算的一个重要组成部分，随着围绕容器的基础设施的发展，新的和更好的工具开始浮出水面。过去，你只需用 ",-1)),i(a,{href:"https://opensource.com/article/18/11/behind-scenes-linux-containers"},{default:e(()=>[...s[0]||(s[0]=[n("LXC",-1)])]),_:1}),s[3]||(s[3]=n(" 就可以运行容器，然而随着 Docker 得到了普及，它开始变得越来越复杂。最终，我们在 ",-1)),i(a,{href:"http://podman.io"},{default:e(()=>[...s[1]||(s[1]=[n("Podman",-1)])]),_:1}),s[4]||(s[4]=n(" 得到了我们所期望的容器管理系统：一个无守护进程的容器引擎，它使容器和吊舱易于构建、运行和管理。",-1))]),s[25]||(s[25]=t("p",null,[n("容器直接与 Linux 内核能力（如控制组和命名空间）交互，它们在这些命名空间中产生大量的新进程。简而言之，运行一个容器实际上就是在 Linux 系统内部运行一个 Linux 系统。从操作系统的角度来看，它看起来非常像一种管理和特权活动。普通用户通常不能像容器那样自由支配系统资源，所以默认情况下，运行 Podman 需要 root 或 "),t("code",null,"sudo"),n(" 权限。然而，这只是默认设置，而且这绝不是唯一可用的设置。本文演示了如何配置你的 Linux 系统，使普通用户可以在不使用 "),t("code",null,"sudo"),n(" 的情况下（“"),t("ruby",null,[n("无根"),t("rt",null,"rootless")]),n("”）运行 Podman。")],-1)),s[26]||(s[26]=t("h3",{id:"命名空间的用户-id",tabindex:"-1"},[n("命名空间的用户 ID "),t("a",{class:"header-anchor",href:"#命名空间的用户-id","aria-label":"Permalink to “命名空间的用户 ID”"},"​")],-1)),t("p",null,[i(a,{href:"https://opensource.com/article/19/10/namespaces-and-containers-linux"},{default:e(()=>[...s[5]||(s[5]=[n("内核命名空间",-1)])]),_:1}),s[6]||(s[6]=n(" 本质上是一种虚构的结构，可帮助 Linux 跟踪哪些进程属于同一类。这是 Linux 中的“队列护栏”。一个队列中的进程与另一个队列中的进程之间实际上没有区别，但可以将它们用“警戒线”彼此隔离。要声明一组进程为“容器”，而另一组进程为你的操作系统，将它们分开是关键。",-1))]),s[27]||(s[27]=u(`<p>Linux 通过用户 ID（UID）和组 ID（GID）来跟踪哪个用户或组拥有的进程。通常情况下，一个用户可以访问一千个左右的从属 UID，以分配给命名空间的子进程。由于 Podman 运行的是分配给启动容器的用户的整个从属操作系统，因此你需要的不仅仅是默认分配的从属 UID 和从属 GID。</p><p>你可以用 <code>usermod</code> 命令授予一个用户更多的从属 UID 和从属 GID。例如，要授予用户 <code>tux</code> 更多的从属 UID 和从属 GID，选择一个还没分配用户的适当的高 UID（如 200000），然后将其增加几千：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod \\</span></span>
<span class="line"><span>    --add-subuids 200000-265536 \\</span></span>
<span class="line"><span>    --add-subgids 200000-265536 \\</span></span>
<span class="line"><span>    tux</span></span></code></pre></div><h3 id="命名空间访问" tabindex="-1">命名空间访问 <a class="header-anchor" href="#命名空间访问" aria-label="Permalink to “命名空间访问”">​</a></h3><p>对命名空间数量也有限制。这通常被设置得很高。你可以用 <code>systctl</code>，即内核参数工具来验证用户的命名空间分配：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sysctl --all --pattern user_namespaces</span></span>
<span class="line"><span>user.max_user_namespaces = 28633</span></span></code></pre></div><p>这是很充足的命名空间，而且可能是你的发行版默认设置的。如果你的发行版没有这个属性或者设置得很低，那么你可以在文件 <code>/etc/sysctl.d/userns.conf</code> 中输入这样的文本来创建它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>user.max_user_namespaces=28633</span></span></code></pre></div><p>加载该设置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysctl -p /etc/sysctl.d/userns.conf</span></span></code></pre></div><h3 id="在没有-root-权限的情况下运行一个容器" tabindex="-1">在没有 root 权限的情况下运行一个容器 <a class="header-anchor" href="#在没有-root-权限的情况下运行一个容器" aria-label="Permalink to “在没有 root 权限的情况下运行一个容器”">​</a></h3><p>当你设置好你的配置，重启你的计算机，以确保你的用户和内核参数的变化被加载和激活。</p><p>重启后，试着运行一个容器镜像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ podman run -it busybox echo &quot;hello&quot;</span></span>
<span class="line"><span>hello</span></span></code></pre></div><h3 id="容器像命令一样" tabindex="-1">容器像命令一样 <a class="header-anchor" href="#容器像命令一样" aria-label="Permalink to “容器像命令一样”">​</a></h3><p>如果你是第一次接触容器，可能会觉得很神秘，但实际上，它们与你现有的 Linux 系统没有什么不同。它们实际上是在你的系统上运行的进程，没有仿真环境或虚拟机的成本和障碍。容器和你的操作系统之间的区别只是内核命名空间，所以它们实际上只是带有不同标签的本地进程。Podman 使这一点比以往更加明显，当你将 Podman 配置为无根命令，容器感觉更像命令而不是虚拟环境。Podman 使容器和吊舱变得简单，所以请试一试。</p><hr>`,17)),t("p",null,[s[8]||(s[8]=n("via: ",-1)),i(a,{href:"https://opensource.com/article/22/1/run-containers-without-sudo-podman"},{default:e(()=>[...s[7]||(s[7]=[n("https://opensource.com/article/22/1/run-containers-without-sudo-podman",-1)])]),_:1})]),t("p",null,[s[13]||(s[13]=n("作者：",-1)),i(a,{href:"https://opensource.com/users/seth"},{default:e(()=>[...s[9]||(s[9]=[n("Seth Kenlon",-1)])]),_:1}),s[14]||(s[14]=n(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[10]||(s[10]=[n("lujun9972",-1)])]),_:1}),s[15]||(s[15]=n(" 译者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:e(()=>[...s[11]||(s[11]=[n("geekpi",-1)])]),_:1}),s[16]||(s[16]=n(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[12]||(s[12]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[19]||(s[19]=n("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[17]||(s[17]=[n("LCTT",-1)])]),_:1}),s[20]||(s[20]=n(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...s[18]||(s[18]=[n("Linux中国",-1)])]),_:1}),s[21]||(s[21]=n(" 荣誉推出",-1))])])}const P=o(r,[["render",h]]);export{c as __pageData,P as default};
